package com.hospital.platform.common.error;
import com.hospital.platform.common.api.ApiResponse; import com.hospital.platform.common.trace.TraceId;
import jakarta.validation.ConstraintViolationException; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.validation.FieldError; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);
 @ExceptionHandler(BusinessException.class) ResponseEntity<ApiResponse<Void>> business(BusinessException e){HttpStatus s=e.errorCode()==ErrorCode.FORBIDDEN||e.errorCode()==ErrorCode.MEMBER_NOT_OWNED||e.errorCode()==ErrorCode.APPOINTMENT_NOT_OWNED||e.errorCode()==ErrorCode.CLINICAL_ACCESS_DENIED||e.errorCode()==ErrorCode.DIAGNOSTIC_ACCESS_DENIED?HttpStatus.FORBIDDEN:e.errorCode()==ErrorCode.NOT_FOUND?HttpStatus.NOT_FOUND:e.errorCode()==ErrorCode.RATE_LIMITED?HttpStatus.TOO_MANY_REQUESTS:e.errorCode()==ErrorCode.MASTER_CONFLICT||e.errorCode()==ErrorCode.IDENTITY_DUPLICATED||e.errorCode()==ErrorCode.APPOINTMENT_DUPLICATE||e.errorCode()==ErrorCode.APPOINTMENT_IDEMPOTENCY_CONFLICT||e.errorCode()==ErrorCode.QUOTA_NOT_ENOUGH||e.errorCode()==ErrorCode.SCHEDULE_HAS_ACTIVE_APPOINTMENTS||e.errorCode()==ErrorCode.SLOT_HAS_APPOINTMENT_HISTORY||e.errorCode()==ErrorCode.CLINICAL_RECORD_VERSION_CONFLICT||e.errorCode()==ErrorCode.CLINICAL_PRIMARY_DIAGNOSIS_CONFLICT?HttpStatus.CONFLICT:e.errorCode().code().startsWith("AUTH")||e.errorCode()==ErrorCode.PATIENT_DISABLED?HttpStatus.UNAUTHORIZED:HttpStatus.BAD_REQUEST; return ResponseEntity.status(s).body(ApiResponse.failure(e.errorCode().code(),e.getMessage(),TraceId.get()));}
 @ExceptionHandler({MethodArgumentNotValidException.class, ConstraintViolationException.class}) ResponseEntity<ApiResponse<Void>> validation(Exception e){String m=e instanceof MethodArgumentNotValidException x && x.getBindingResult().getFieldError()!=null?x.getBindingResult().getFieldError().getField()+" 参数不合法":ErrorCode.VALIDATION.message();return ResponseEntity.badRequest().body(ApiResponse.failure(ErrorCode.VALIDATION.code(),m,TraceId.get()));}
 @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> unexpected(Exception e){log.error("Unhandled request failure, traceId={}",TraceId.get(),e);return ResponseEntity.status(500).body(ApiResponse.failure(ErrorCode.SYSTEM.code(),ErrorCode.SYSTEM.message(),TraceId.get()));}
}
